import{_ as n,a0 as s,w as l,s as d,ao as p,I as i,x as r,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux上從MySQL遷移到MariaDB的簡單步驟 | LCTT x X-CMD","titleTemplate":false,"description":"Linux上從MySQL遷移到MariaDB的簡單步驟 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux上從MySQL遷移到MariaDB的簡單步驟 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux上從MySQL遷移到MariaDB的簡單步驟 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150211 Simple Steps Migration From MySQL To MariaDB On Linux","title":"Linux上從MySQL遷移到MariaDB的簡單步驟","tag":"201504","desc":""},"relativePath":"201504/20150211 Simple Steps Migration From MySQL To MariaDB On Linux.md","filePath":"[post].md"}'),m={name:"201504/20150211 Simple Steps Migration From MySQL To MariaDB On Linux.md"};function g(y,a,u,c,b,M){const t=s("Link");return l(),d("div",null,[a[16]||(a[16]=p(`<h1 id="linux上從mysql遷移到mariadb的簡單步驟" tabindex="-1">Linux上從MySQL遷移到MariaDB的簡單步驟 <a class="header-anchor" href="#linux上從mysql遷移到mariadb的簡單步驟" aria-label="Permalink to “Linux上從MySQL遷移到MariaDB的簡單步驟”">​</a></h1><p>大家好！這是一篇介紹如何在服務器或個人電腦上從MySQL遷移到MariaDB的教程。也許你會問為什麼我們要將資料庫管理從MySQL遷移到MariaDB。往下看我們告訴你為什麼這樣做。</p><h3 id="為什麼要用mariadb來代替mysql" tabindex="-1">為什麼要用MariaDB來代替MySQL <a class="header-anchor" href="#為什麼要用mariadb來代替mysql" aria-label="Permalink to “為什麼要用MariaDB來代替MySQL”">​</a></h3><p>MariaDB是MySQL社區開發的分支，也是一個增強型的替代品。它由MySQL前開發者們帶頭組織的基金會開發，使用起來和MySQL完全一樣。自從Oracle買下了MySQL，它就不再自由開源了，但是 <strong>MariaDB仍然自由開源</strong>。一些如谷歌、維基、LinkedIn、Mozilla等的頂級的網站已經遷移到MariaDB了。它的優勢在哪裏：</p><ul><li>向後兼容MySQL</li><li>永遠開源</li><li>由MySQL締造者的維護</li><li>更尖端的功能</li><li>更多的存儲引擎</li><li>大型的網站已經轉向MariaDB</li></ul><p>現在，讓我們遷移到MariaDB吧！</p><p>讓我們創建一個叫<strong>linoxidedb</strong>的<strong>用於測試的</strong>示例資料庫。</p><p>使用以下命令用root賬户登陸MySQL：</p><pre><code>$ mysql -u root -p
</code></pre><p>輸入mysql 的 root 用户密碼後，你將進入<strong>mysql的命令列</strong></p><p><strong>創建測試資料庫:</strong></p><p>在mysql命令列輸入以下命令以創建測試資料庫。</p><pre><code>mysql&gt; create database linoxidedb;
</code></pre><p>查看可用的資料庫，輸入以下命令：</p><pre><code>mysql&gt; show databases;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/creating-test-databases.png" alt="creating test databases"></p><p>如你所見，算上剛剛新建的linoxidedb我們一共有5個數據庫。</p><pre><code>mysql&gt; quit
</code></pre><p>現在，我們就將剛創建的資料庫從MySQL遷移到MariaDB。</p><p>注：使用CentOS這類基於fedora的linux發行版沒有必要參考這篇教程，因為它們在安裝MariaDB時會自動代替MySQL，無需備份現有的資料庫，你只需要更新mysql就可以得到mariadb。</p><h3 id="_1-備份現有的資料庫" tabindex="-1">1. 備份現有的資料庫 <a class="header-anchor" href="#_1-備份現有的資料庫" aria-label="Permalink to “1. 備份現有的資料庫”">​</a></h3><p>我們第一個重要的步驟就是備份現有的資料庫。我們在<strong>終端（不是MySQL命令列）</strong>裏輸入如下命令來完成備份。</p><pre><code>$ mysqldump --all-databases --user=root --password --master-data &gt; backupdatabase.sql
</code></pre><p>哇哦！我們遇到了點麻煩。別擔心我們可以搞定。</p><pre><code>$ mysqldump: Error: Binlogging on server not active
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mysqldump-error.png" alt=""></p><p><em>mysqldump error</em></p><p>為了修復這個錯誤，我們需要對<strong>my.cnf</strong>文件做一些小改動。</p><p>編輯my.cnf文件：</p><pre><code>$ sudo nano /etc/mysql/my.cnf
</code></pre><p>在[mysqld]部分添加如下參數。</p><p><strong>log-bin=mysql-bin</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configuring-my.cnf_.png" alt="configuring my.cnf"></p><p>好了，在保存並關閉文件後，我們需要重啓一下mysql服務。運行以下命令重啓：</p><pre><code>$ sudo /etc/init.d/mysql restart
</code></pre><p>現在，重新運行mysqldump命令來備份所有的資料庫。</p><pre><code>$ mysqldump --all-databases --user=root --password --master-data &gt; backupdatabase.sql
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/crearing-bakup-file.png" alt=""></p><p><em>dumping databases</em></p><p>上面的命令將會備份所有的資料庫，把它們存儲在當前目錄下的<strong>backupdatabase.sql</strong>文件中。</p><h3 id="_2-卸載mysql" tabindex="-1">2. 卸載MySQL <a class="header-anchor" href="#_2-卸載mysql" aria-label="Permalink to “2. 卸載MySQL”">​</a></h3><p>首先，我們得把<strong>my.cnf文件挪到安全的地方去</strong>。</p><p><strong>注</strong>：在你卸載MySQL包的時候不會自動刪除my.cnf文件，我們這樣做只是以防萬一。在MariaDB安裝時，它會詢問我們是保持現存的my.cnf文件，還是使用包中自帶的版本（即新my.cnf文件）。</p><p>在shell或終端中輸入如下命令來備份my.cnf文件：</p><pre><code>$ sudo cp /etc/mysql/my.cnf my.cnf.bak
</code></pre><p>運行命令來終止mysql服務：</p><pre><code>$ sudo /etc/init.d/mysql stop
</code></pre><p>然後移除mysql包：</p><pre><code>$ sudo apt-get remove mysql-server mysql-client
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/uninstalling-mysql.png" alt="uninstalling mysql"></p><h3 id="_3-安裝mariadb" tabindex="-1">3. 安裝MariaDB <a class="header-anchor" href="#_3-安裝mariadb" aria-label="Permalink to “3. 安裝MariaDB”">​</a></h3><p>這是在Ubuntu系統中安裝MariaDB的命令：</p><pre><code>$ sudo apt-get install software-properties-common
$ sudo apt-key adv --recv-keys --keyserver hkp://keyserver.ubuntu.com:80 0xcbcb082a1bb943db
# sudo add-apt-repository &#39;deb http://mirror.mephi.ru/mariadb/repo/5.5/ubuntu trusty main&#39;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/adding-repo-mariadb.png" alt="adding mariadb repo"></p><p>鍵值導入並且添加完倉庫後，你就可以用以下命令安裝MariaDB了：</p><pre><code>$ sudo apt-get update
$ sudo apt-get install mariadb-server
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/installing-mariadb.png" alt="installing mariadb"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/my.conf-configuration-prompt.png" alt="my.conf configuration prompt"></p>`,58)),i("p",null,[a[1]||(a[1]=r("我們應該還沒忘記在MariaDB安裝時，它會問你是使用現有的my.cnf文件，還是包中自帶的版本。你可以使用以前的my.cnf也可以用包中自帶的。即使你想直接使用新的my.cnf文件，你依然可以晚點時候將以前的備份內容還原進去（別忘了我們已經將它複製到安全的地方了）。所以，我們直接選擇了默認的選項“N”。如果需要安裝其他版本，請參考",-1)),e(t,{href:"https://downloads.mariadb.org/mariadb/repositories/#mirror=mephi"},{default:o(()=>[...a[0]||(a[0]=[r("MariaDB官方倉庫",-1)])]),_:1}),a[2]||(a[2]=r("。",-1))]),a[17]||(a[17]=p(`<h3 id="_4-恢復配置文件" tabindex="-1">4. 恢復配置文件 <a class="header-anchor" href="#_4-恢復配置文件" aria-label="Permalink to “4. 恢復配置文件”">​</a></h3><p>想要將my.cnf.bak中的內容恢復到my.cnf，在終端中輸入以下命令。由於my.cnf.bak文件在當前目錄下，所以我們只要簡單的執行以下命令即可：</p><pre><code>$ sudo cp my.cnf.bak /etc/mysql/my.cnf
</code></pre><h3 id="_5-導入資料庫" tabindex="-1">5. 導入資料庫 <a class="header-anchor" href="#_5-導入資料庫" aria-label="Permalink to “5. 導入資料庫”">​</a></h3><p>最後，讓我們把我們之前創建的資料庫導入吧！運行一下命令即可完成導入。</p><pre><code>$ mysql -u root -p &lt; backupdatabase.sql
</code></pre><p>就這樣，我們已成功將之前的資料庫導入了進來。</p><p>來，讓我們登錄一下mysql命令列，檢查一下資料庫是否真的已經導入了：</p><pre><code>$ mysql -u root -p
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/importing-database.png" alt="importing database"></p><p>為了檢查資料庫是否被遷移到MariaDB，請在MariaDB命令列中輸入“<strong>show databases</strong>；”不用輸入（“”），如下：</p><pre><code>mariaDB&gt; show databases;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/maria-database-migrated.png" alt="mysql to mariadb database migrated"></p><p>如你所見，linoxidedb及所有的資料庫都已經成功的被遷移了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>最後，我們已經成功地從MySQL遷移到了MariaDB資料庫管理系統。MariaDB比MySQL好，雖然在性能方面MySQL還是比它更快，但是MariaDB的優點在於它額外的特性與支持的許可證。這能夠確保它自由開源（FOSS），並永久自由開源，相比之下MySQL還有許多額外的插件，有些不能自由使用代碼、有些沒有公開的開發進程、有些在不久的將來會變的不再自由開源。如果你有任何的問題、評論、反饋給我們，不要猶豫直接在評論區留下你的看法。謝謝觀看本教程，希望你能喜歡MariaDB。</p><hr>`,17)),i("p",null,[a[4]||(a[4]=r("via: ",-1)),e(t,{href:"http://linoxide.com/linux-how-to/migrate-mysql-mariadb-linux/"},{default:o(()=>[...a[3]||(a[3]=[r("http://linoxide.com/linux-how-to/migrate-mysql-mariadb-linux/",-1)])]),_:1})]),i("p",null,[a[8]||(a[8]=r("作者：",-1)),e(t,{href:"http://linoxide.com/author/arunp/"},{default:o(()=>[...a[5]||(a[5]=[r("Arun Pyasi",-1)])]),_:1}),a[9]||(a[9]=r(" 譯者：",-1)),e(t,{href:"https://github.com/martin2011qi"},{default:o(()=>[...a[6]||(a[6]=[r("martin2011qi",-1)])]),_:1}),a[10]||(a[10]=r(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:o(()=>[...a[7]||(a[7]=[r("wxy",-1)])]),_:1})]),i("p",null,[a[13]||(a[13]=r("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[11]||(a[11]=[r("LCTT",-1)])]),_:1}),a[14]||(a[14]=r(" 原創翻譯，",-1)),e(t,{href:"http://linux.cn/"},{default:o(()=>[...a[12]||(a[12]=[r("Linux中國",-1)])]),_:1}),a[15]||(a[15]=r(" 榮譽推出",-1))])])}const S=n(m,[["render",g]]);export{L as __pageData,S as default};
